1	// Deno Deploy / Supabase Edge Function for Resend webhook
2	// deno-lint-ignore-file no-explicit-any
3	import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
4	import { Webhook } from 'https://esm.sh/svix@1.15.0';
5	import { ocrFromUrl, processEmailText, textToImage } from '../_shared/mistral.ts';
6	import { resolveOcrReceiptDate } from '../_shared/receiptDateCorrection.ts';
7	import { fetchExchangeRate } from '../_shared/exchangeRate.ts';
8	import {
9		isSupportedReceiptType,
10		isInlineAttachment,
11		hasUsableOcrData,
12		hasSupportedAttachments
13	} from '../_shared/attachmentFiltering.ts';
14	
15	interface ResendAttachmentMetadata {
16		id: string;
17		filename: string;
18		content_type: string;
19		content_disposition?: string;
20		content_id?: string;
21	}
22	
23	interface ResendWebhookEvent {
24		type: string;
25		created_at: string;
26		data: {
27			email_id: string;
28			from: string;
29			to: string[];
30			subject: string;
31			created_at: string;
32			message_id: string;
33			bcc: string[];
34			cc: string[];
35			attachments: ResendAttachmentMetadata[];
36		};
37	}
38	
39	interface ResendEmail {
40		email_id: string;
41		from: string;
42		to: string[];
43		subject: string;
44		html: string | null;
45		text: string | null;
46		headers: Record<string, string>;
47	}
48	
49	interface ResendAttachment {
50		filename: string;
51		content_type: string;
52		size: number;
53		download_url: string;
54		expires_at: string;
55	}
