64	/**
65	 * Verifies the Resend webhook signature using Svix library
66	 * Based on: https://resend.com/docs/dashboard/webhooks/verify-webhooks-requests
67	 */
68	function verifyWebhookSignature(headers: Headers, payload: string, signingSecret: string): boolean {
69		const svixId = headers.get('svix-id');
70		const svixTimestamp = headers.get('svix-timestamp');
71		const svixSignature = headers.get('svix-signature');
72	
73		console.log('Signature verification headers:', {
74			hasSignature: !!svixSignature,
75			hasTimestamp: !!svixTimestamp,
76			hasId: !!svixId
77		});
78	
79		if (!svixId || !svixTimestamp || !svixSignature) {
80			console.error('Missing webhook signature headers:', {
81				signature: svixSignature ? 'present' : 'missing',
82				timestamp: svixTimestamp ? 'present' : 'missing',
83				id: svixId ? 'present' : 'missing'
84			});
85			return false;
86		}
87	
88		try {
89			const wh = new Webhook(signingSecret);
90	
91			// Verify the webhook - this will throw on error
92			wh.verify(payload, {
93				'svix-id': svixId,
94				'svix-timestamp': svixTimestamp,
95				'svix-signature': svixSignature
96			});
97	
98			console.log('Webhook signature verified successfully');
99			return true;
100		} catch (err) {
101			console.error('Webhook signature verification failed:', err);
102			return false;
103		}
104	}
