106	async function uploadToStorage(
107		supabase: any,
108		userId: string,
109		bytes: Uint8Array,
110		contentType: string,
111		ext: string
112	): Promise<{ path: string; signedUrl: string }> {
113		const path = `${userId}/${crypto.randomUUID()}.${ext}`;
114		const { error } = await supabase.storage
115			.from('receipts')
116			.upload(path, bytes, { contentType, upsert: false });
117		if (error) throw error;
118		// #{#sec1b} Use signed URL — receipts bucket is private (#{#sec1a})
119		// 5-minute expiry matches OCR signed URL pattern in ReceiptService.ts
120		const { data, error: signError } = await supabase.storage
121			.from('receipts')
122			.createSignedUrl(path, 300);
123		if (signError) throw signError;
124		return { path, signedUrl: data.signedUrl };
125	}
126	
127	// #{#fcr1a} #{#fcr2a} Best-effort exchange rate lookup for foreign currency receipts.
128	// Returns null if currency is CAD/unknown, date is missing, or the API call fails —
129	// matches ReceiptService.uploadAndCreate so the receipt still saves without a rate.
130	async function fetchRateForReceipt(
131		currency: string | null | undefined,
132		transactionDate: string | null | undefined
133	): Promise<number | null> {
134		if (!currency || currency === 'CAD' || !transactionDate) return null;
135		try {
136			return await fetchExchangeRate(currency, transactionDate);
137		} catch (err) {
138			console.error('Exchange rate fetch failed:', err);
139			return null;
140		}
141	}
