143	async function insertReceipt(supabase: any, receiptData: any): Promise<any> {
144		console.log('Attempting to insert receipt with RPC...');
145		// Use RPC to insert with proper user context
146		const { data, error } = await supabase.rpc('insert_receipt_with_context', {
147			receipt_data: receiptData
148		});
149	
150		if (error) {
151			console.error('RPC insert failed:', JSON.stringify(error, null, 2));
152			console.log('Falling back to direct insert...');
153	
154			// Fallback to direct insert - bypass RLS with service role
155			const { data: directData, error: directError } = await supabase
156				.from('receipts')
157				.insert(receiptData)
158				.select('*')
159				.single();
160	
161			if (directError) {
162				console.error('Direct insert also failed:', JSON.stringify(directError, null, 2));
163				throw directError;
164			}
165			console.log('Direct insert succeeded');
166			return directData;
167		}
168	
169		console.log('RPC insert succeeded');
170		return data;
171	}
