173	/**
174	 * Send email notification to user about receipt processing status
175	 */
176	async function sendNotificationEmail(
177		apiKey: string,
178		toEmail: string,
179		notificationType: 'error' | 'warning' | 'success',
180		title: string,
181		message: string,
182		originalSubject: string,
183		emailId?: string
184	): Promise<void> {
185		try {
186			const iconMap = {
187				error: '❌',
188				warning: '⚠️',
189				success: '✅'
190			};
191	
192			const colorMap = {
193				error: '#dc2626',
194				warning: '#f59e0b',
195				success: '#16a34a'
196			};
197	
198			const subjectPrefix = {
199				error: 'Failed',
200				warning: 'Warning',
201				success: 'Success'
202			};
203	
204			const icon = iconMap[notificationType];
205			const color = colorMap[notificationType];
206			const subject = `Receipt ${subjectPrefix[notificationType]}: "${originalSubject}"`;
207	
208			const html = `
209	<!DOCTYPE html>
210	<html>
211	<head>
212		<style>
213			body {
214				font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
215				line-height: 1.6;
216				color: #333;
217			}
218			.container {
219				max-width: 600px;
220				margin: 0 auto;
221				padding: 20px;
222			}
223			.header {
224				text-align: center;
225				padding: 20px 0;
226			}
227			.icon {
228				font-size: 48px;
229				margin-bottom: 10px;
230			}
231			.notification-box {
232				background: #f9fafb;
233				border-left: 4px solid ${color};
234				padding: 20px;
235				margin: 20px 0;
236				border-radius: 4px;
237			}
238			.notification-box h2 {
239				margin-top: 0;
240				color: ${color};
241			}
242			.actions {
243				background: #ffffff;
244				border: 1px solid #e5e7eb;
245				border-radius: 8px;
246				padding: 20px;
247				margin: 20px 0;
248			}
249			.actions h3 {
250				margin-top: 0;
251				font-size: 16px;
252			}
253			.actions ul {
254				margin: 10px 0;
255				padding-left: 20px;
256			}
257			.actions li {
258				margin: 8px 0;
259			}
260			.cta-button {
261				display: inline-block;
262				background: #2563eb;
263				color: white !important;
264				padding: 12px 24px;
265				text-decoration: none;
266				border-radius: 6px;
267				margin: 15px 0 5px 0;
268				font-weight: 500;
269			}
270			.footer {
271				margin-top: 30px;
272				padding-top: 20px;
273				border-top: 1px solid #e5e7eb;
274				color: #6b7280;
275				font-size: 13px;
276			}
277			.footer-info {
278				margin: 5px 0;
279			}
280		</style>
281	</head>
282	<body>
283		<div class="container">
284			<div class="header">
285				<div class="icon">${icon}</div>
286			</div>
287	
288			<div class="notification-box">
289				<h2>${title}</h2>
290				<p>${message}</p>
291			</div>
292	
293			${
294				notificationType === 'error' || notificationType === 'warning'
295					? `
296			<div class="actions">
297				<h3>What you can do:</h3>
298				<ul>
299					<li>📸 Forward the email again with a clearer, well-lit photo</li>
300					<li>📄 Send the receipt as a PDF attachment instead of an image</li>
301					<li>🖼️ Make sure the entire receipt is visible and in focus</li>
302					<li>💻 Upload directly through the web app (see button below)</li>
303				</ul>
304				<a href="https://app.yourfinanciallaunchpad.com/receipts" class="cta-button">
305					Upload Receipt Directly
306				</a>
307			</div>
308			`
309					: ''
310			}
311	
312			<div class="footer">
313				<div class="footer-info"><strong>Original email:</strong> "${originalSubject}"</div>
314				<div class="footer-info"><strong>Sent at:</strong> ${new Date().toLocaleString()}</div>
315				${emailId ? `<div class="footer-info"><strong>Email ID:</strong> ${emailId}</div>` : ''}
316				<div class="footer-info" style="margin-top: 15px;">
317					<em>This is an automated notification from your expense tracker.</em>
318				</div>
319			</div>
320		</div>
321	</body>
322	</html>
323			`;
324	
325			const response = await fetch('https://api.resend.com/emails', {
326				method: 'POST',
327				headers: {
328					Authorization: `Bearer ${apiKey}`,
329					'Content-Type': 'application/json'
330				},
331				body: JSON.stringify({
332					from: 'Expense Tracker <test@expenseapp.yourfinanciallaunchpad.com>',
333					to: [toEmail],
334					subject: subject,
335					html: html
336				})
337			});
338	
339			if (!response.ok) {
340				const errorText = await response.text();
341				console.error('Failed to send notification email:', response.status, errorText);
342			} else {
343				const result = await response.json();
344				console.log(`Notification email sent to ${toEmail}:`, result);
345			}
346		} catch (err) {
347			console.error('Error sending notification email:', err);
348			// Don't throw - we don't want email sending to break the webhook processing
349		}
350	}
351	
352	Deno.serve(async (req) => {
353		console.log('=== Resend Webhook Request Received ===');
354		console.log('Method:', req.method);
355		console.log('URL:', req.url);
356	
357		if (req.method !== 'POST') {
358			console.log('Rejecting non-POST request');
359			return jsonResponse(405, { error: 'Method not allowed' });
360		}
361	
362		// Read the raw body for signature verification
363		const bodyText = await req.text();
364		console.log('Received webhook payload length:', bodyText.length);
365		console.log('Raw payload:', bodyText.substring(0, 500) + (bodyText.length > 500 ? '...' : ''));
366	
367		let event: ResendWebhookEvent;
368	
369		try {
370			event = JSON.parse(bodyText);
371			console.log('Parsed event type:', event.type);
372			console.log('Event data:', JSON.stringify(event.data));
373		} catch (e) {
374			console.error('Failed to parse JSON:', e);
375			return jsonResponse(400, { error: 'Invalid JSON' });
376		}
377	
378		// Basic validation
379		if (!event.type) {
380			console.error('Missing event type in payload');
381			return jsonResponse(400, { error: 'Missing event type' });
382		}
383	
384		const supabaseUrl = Deno.env.get('SUPABASE_URL');
385		const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
386		const resendApiKey = Deno.env.get('RESEND_API_KEY');
387		const resendWebhookSecret = Deno.env.get('RESEND_WEBHOOK_SECRET');
388	
389		if (!supabaseUrl || !serviceRoleKey) {
390			return jsonResponse(500, { error: 'Missing Supabase env' });
391		}
392		if (!resendApiKey) {
393			console.error('RESEND_API_KEY environment variable is not set');
394			return jsonResponse(500, { error: 'Missing Resend API key' });
395		}
396	
397		console.log(`Resend API key is set (length: ${resendApiKey.length})`);
398	
399		// Log all request headers for debugging
400		console.log('Request headers:', JSON.stringify(Object.fromEntries(req.headers.entries())));
401	
402		// Verify webhook signature if secret is configured
403		if (resendWebhookSecret) {
404			console.log('RESEND_WEBHOOK_SECRET is set, attempting signature verification...');
405			console.log(
406				'RESEND_WEBHOOK_SECRET value (first 10 chars):',
407				resendWebhookSecret.substring(0, 10)
408			);
409			console.log('Secret length:', resendWebhookSecret.length);
410			const isValid = verifyWebhookSignature(req.headers, bodyText, resendWebhookSecret);
411			if (!isValid) {
412				console.error('Invalid webhook signature - TEMPORARILY ALLOWING TO PROCEED FOR DEBUGGING');
413				console.error(
414					'This should be fixed by ensuring the webhook secret matches between Resend and Supabase'
415				);
416				// TODO: Re-enable this after verifying the secret is correct
417				// return jsonResponse(401, { error: 'Invalid webhook signature' });
418			} else {
419				console.log('✅ Webhook signature verification PASSED');
420			}
421		} else {
422			console.log('RESEND_WEBHOOK_SECRET not set - webhook signature verification disabled');
423		}
424	
425		// Only process email.received events
426		if (event.type !== 'email.received') {
427			console.log(`Ignoring event type: ${event.type} - returning success`);
428			return jsonResponse(200, { message: `Event type ${event.type} ignored` });
429		}
430	
431		console.log('Processing email.received event...');
432	
433		const supabase = createClient(supabaseUrl, serviceRoleKey, {
434			auth: {
435				autoRefreshToken: false,
436				persistSession: false
437			}
438		});
439	
440		// Find user by sender email
441		const sender = event.data?.from?.toLowerCase?.();
442		if (!sender) {
443			console.error('Missing sender in event data');
444			return jsonResponse(400, { error: 'Missing sender' });
445		}
446	
447		console.log(`Looking up user by email: ${sender}`);
448		const { data: userIdData, error: userErr } = await supabase.rpc('find_user_by_email', {
449			email_address: sender
450		});
451		if (userErr) {
452			console.error(`Error finding user: ${JSON.stringify(userErr)}`);
453			return jsonResponse(500, { error: userErr.message });
454		}
455		if (!userIdData) {
456			console.error(`No user found for email: ${sender}`);
457			return jsonResponse(404, { error: 'User not found for sender email' });
458		}
459		const userId = userIdData as string;
460		console.log(`Found user ID: ${userId}`);
461	
462		// Fetch the full email content from Resend API to get body text
463		console.log(`Fetching email content for email_id: ${event.data.email_id}`);
464		console.log(
465			`Using API key: ${resendApiKey.substring(0, 7)}...${resendApiKey.substring(resendApiKey.length - 4)}`
466		);
467		console.log(`API endpoint: https://api.resend.com/emails/receiving/${event.data.email_id}`);
468	
469		let emailBodyText = '';
470	
471		try {
472			const emailResponse = await fetch(
473				`https://api.resend.com/emails/receiving/${event.data.email_id}`,
474				{
475					method: 'GET',
476					headers: {
477						Authorization: `Bearer ${resendApiKey}`,
478						'Content-Type': 'application/json'
479					}
480				}
481			);
482	
483			console.log(`Email fetch response status: ${emailResponse.status}`);
484	
485			if (!emailResponse.ok) {
486				const errorText = await emailResponse.text();
487				console.error(`Failed to fetch email: ${emailResponse.status} ${emailResponse.statusText}`);
488				console.error(`Error response body: ${errorText}`);
489				// Don't return error - continue with attachments processing
490			} else {
491				const email: ResendEmail = await emailResponse.json();
492				console.log(
493					`Email fetched successfully. Has text: ${!!email.text}, Has html: ${!!email.html}`
494				);
495				emailBodyText = (email.text || email.html || '').toString();
496			}
497		} catch (e) {
498			console.error('Exception fetching email content:', e);
499			// Continue processing - we can still try attachments
500		}
501	
502		// #{#eaf5a} Check for supported attachments before processing body text
503		const attachmentMetadata = event.data.attachments || [];
504		const hasScannable = hasSupportedAttachments(attachmentMetadata);
505	
506		let inserted: any = null;
507		const processingErrors: string[] = [];
508	
509		// #{#eaf5a} Only process body text if no supported attachments exist
510		if (emailBodyText && !hasScannable) {
511			console.log('No supported attachments found, processing email body text');
512		} else if (hasScannable) {
513			console.log(
514				`Skipping body text extraction — ${attachmentMetadata.length} supported attachment(s) found`
515			);
516		}
517	
518		if (emailBodyText && !hasScannable) {
519			try {
520				console.log('Processing email body text with Mistral...');
521				const extracted = await processEmailText(emailBodyText);
522	
523				if (extracted) {
524					console.log('Mistral found receipt data:', JSON.stringify(extracted, null, 2));
525	
526					// Convert the text to an image
527					console.log('Converting text to image...');
528					const imageBytes = await textToImage(emailBodyText);
529					const { path, signedUrl } = await uploadToStorage(
530						supabase,
531						userId,
532						imageBytes,
533						'image/svg+xml',
534						'svg'
535					);
536					console.log('Image uploaded to:', signedUrl);
537	
538					// Insert receipt with the text-as-image
539					try {
540						console.log('Inserting receipt for user:', userId);
541	
542						// #{#rdc4c} #{#rdc5a} Correct the OCR date from the verbatim raw string, then
543						// flag suspicious dates (#{#dtv4a}). Uncorrectable wrong-token reads are flagged.
544						const resolved = resolveOcrReceiptDate(
545							extracted.transaction_date ?? null,
546							extracted.raw_date_text ?? null,
547							new Date()
548						);
549						extracted.transaction_date = resolved.transaction_date;
550						const suspicious = resolved.suspicious_date;
551						if (suspicious) {
552							console.log(
553								`Warning: Suspicious date detected for email receipt: ${extracted.transaction_date}`
554							);
555	
556							// Notify user about suspicious date
557							await sendNotificationEmail(
558								resendApiKey,
559								sender,
560								'warning',
561								'Please Check Receipt Date',
562								`The receipt date we found (${extracted.transaction_date}) seems unusual - it's either more than 6 weeks old or in the future. We've saved the receipt, but please verify the date is correct and update it if needed.`,
563								event.data.subject,
564								event.data.email_id
565							);
566						}
567	
568						// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
569						const exchangeRate = await fetchRateForReceipt(
570							extracted.currency,
571							extracted.transaction_date
572						);
573	
574						inserted = await insertReceipt(supabase, {
575							user_id: userId,
576							receipt_image_path: path,
577							merchant_name: extracted.merchant_name,
578							total_amount: extracted.total_amount,
579							tax: extracted.tax,
580							transaction_date: extracted.transaction_date,
581							currency: extracted.currency,
582							exchange_rate_to_cad: exchangeRate,
583							credit_card_name: extracted.credit_card_name,
584							credit_card_last_4: extracted.credit_card_last_4,
585							suspicious_date: suspicious
586						});
587						console.log('Receipt inserted successfully:', inserted?.id);
588					} catch (insertErr: any) {
589						const msg = `Body text insert failed: ${insertErr?.message || JSON.stringify(insertErr)}`;
590						console.error(msg);
591						processingErrors.push(msg);
592					}
593				} else {
594					console.log('No receipt data found in email body text');
595					// Don't send notification yet - we'll try attachments first
596				}
597			} catch (e) {
598				const msg = `Body text processing error: ${(e as any)?.message || e}`;
599				console.error(msg);
600				processingErrors.push(msg);
601			}
602		}
603	
604		// Process attachments (either as primary path or fallback from body text)
605		if (!inserted) {
606			console.log(`Found ${attachmentMetadata.length} attachment(s) in webhook payload`);
607	
608			if (attachmentMetadata.length === 0) {
609				console.log('No attachments to process');
610			} else {
611				// Fetch attachment download URLs from Resend API
612				console.log(`Fetching attachment download URLs for email_id: ${event.data.email_id}`);
613	
614				try {
615					const attachmentsResponse = await fetch(
616						`https://api.resend.com/emails/receiving/${event.data.email_id}/attachments`,
617						{
618							method: 'GET',
619							headers: {
620								Authorization: `Bearer ${resendApiKey}`,
621								'Content-Type': 'application/json'
622							}
623						}
624					);
625	
626					console.log(`Attachments fetch response status: ${attachmentsResponse.status}`);
627	
628					if (!attachmentsResponse.ok) {
629						const errorText = await attachmentsResponse.text();
630						const msg = `Resend attachment fetch failed: ${attachmentsResponse.status} ${attachmentsResponse.statusText} — ${errorText}`;
631						console.error(msg);
632						processingErrors.push(msg);
633					} else {
634						const attachmentsData = await attachmentsResponse.json();
635						console.log(`Attachments response data: ${JSON.stringify(attachmentsData)}`);
636						const attachments: ResendAttachment[] = attachmentsData.data || [];
637	
638						console.log(`Received ${attachments.length} attachment download URL(s)`);
639	
640						let processedCount = 0;
641	
642						for (const att of attachments) {
643							try {
644								// #{#eaf2a} Skip inline attachments (signatures, logos)
645								if (
646									isInlineAttachment({
647										filename: att.filename,
648										content_type: att.content_type,
649										content_id: (att as any).content_id,
650										content_disposition: (att as any).content_disposition
651									})
652								) {
653									console.log(
654										`Skipping inline attachment: ${att.filename} (content_id: ${(att as any).content_id})`
655									);
656									continue;
657								}
658	
659								// #{#eaf1a} Filter by supported MIME types
660								const ct = att.content_type || 'application/octet-stream';
661								if (!isSupportedReceiptType(ct, att.filename)) {
662									console.log(`Skipping unsupported attachment type: ${ct} (${att.filename})`);
663									continue;
664								}
665	
666								console.log(`Processing attachment: ${att.filename}`);
667	
668								// Download attachment using the provided download_url
669								const downloadResponse = await fetch(att.download_url);
670								if (!downloadResponse.ok) {
671									const msg = `Download failed for ${att.filename}: HTTP ${downloadResponse.status}`;
672									console.error(msg);
673									processingErrors.push(msg);
674	
675									// Notify user about attachment download failure
676									await sendNotificationEmail(
677										resendApiKey,
678										sender,
679										'error',
680										'Attachment Download Failed',
681										`We couldn't download the attachment "${att.filename}" from your email. Resend attachments expire after 30 minutes, so the download link may have expired. Please try forwarding the email again.`,
682										event.data.subject,
683										event.data.email_id
684									);
685	
686									continue;
687								}
688	
689								const bytes = new Uint8Array(await downloadResponse.arrayBuffer());
690								const ext = (att.filename?.split('.')?.pop() || 'bin').toLowerCase();
691	
692								const { path, signedUrl } = await uploadToStorage(supabase, userId, bytes, ct, ext);
693								const extracted = await ocrFromUrl(signedUrl, ct).catch(async (err) => {
694									const msg = `OCR failed for ${att.filename}: ${err?.message || err}`;
695									console.error(msg);
696									processingErrors.push(msg);
697	
698									// Notify user about OCR failure
699									await sendNotificationEmail(
700										resendApiKey,
701										sender,
702										'error',
703										'Receipt Reading Failed',
704										`We couldn't extract receipt information from "${att.filename}". The image or PDF may be unclear, too dark, or rotated. Please try sending a clearer, well-lit photo of the receipt.`,
705										event.data.subject,
706										event.data.email_id
707									);
708	
709									return null;
710								});
711	
712								// #{#eaf3a} Validate OCR results before inserting
713								if (!extracted || !hasUsableOcrData(extracted)) {
714									const msg = `OCR returned no usable data for: ${att.filename} (merchant: ${extracted?.merchant_name ?? 'null'}, amount: ${extracted?.total_amount ?? 'null'})`;
715									console.log(msg);
716									processingErrors.push(msg);
717									continue;
718								}
719	
720								console.log('Inserting receipt from attachment for user:', userId);
721	
722								// #{#rdc4c} #{#rdc5a} Correct the OCR date from the verbatim raw string, then
723								// flag suspicious dates (#{#dtv4a}). Uncorrectable wrong-token reads are flagged.
724								const resolved = resolveOcrReceiptDate(
725									extracted.transaction_date ?? null,
726									extracted.raw_date_text ?? null,
727									new Date()
728								);
729								extracted.transaction_date = resolved.transaction_date;
730								const suspicious = resolved.suspicious_date;
731								if (suspicious) {
732									console.log(
733										`Warning: Suspicious date detected for email attachment receipt: ${extracted.transaction_date}`
734									);
735	
736									// Notify user about suspicious date
737									await sendNotificationEmail(
738										resendApiKey,
739										sender,
740										'warning',
741										'Please Check Receipt Date',
742										`The receipt date we found (${extracted.transaction_date}) from "${att.filename}" seems unusual - it's either more than 6 weeks old or in the future. We've saved the receipt, but please verify the date is correct and update it if needed.`,
743										event.data.subject,
744										event.data.email_id
745									);
746								}
747	
748								// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
749								const exchangeRate = await fetchRateForReceipt(
750									extracted.currency,
751									extracted.transaction_date
752								);
753	
754								inserted = await insertReceipt(supabase, {
755									user_id: userId,
756									receipt_image_path: path,
757									transaction_date: extracted.transaction_date,
758									total_amount: extracted.total_amount,
759									tax: extracted.tax,
760									merchant_name: extracted.merchant_name,
761									currency: extracted.currency,
762									exchange_rate_to_cad: exchangeRate,
763									credit_card_name: extracted.credit_card_name,
764									credit_card_last_4: extracted.credit_card_last_4,
765									suspicious_date: suspicious
766								});
767								processedCount++;
768								console.log('Receipt from attachment inserted successfully');
769								// #{#eaf4a} No break — continue processing remaining attachments
770							} catch (e) {
771								const msg = `Attachment error (${att.filename}): ${(e as any)?.message || e}`;
772								console.error(msg);
773								processingErrors.push(msg);
774							}
775						}
776	
777						console.log(
778							`Processed ${processedCount} receipt(s) from ${attachments.length} attachment(s)`
779						);
780					}
781				} catch (e) {
782					const msg = `Exception fetching attachment URLs: ${(e as any)?.message || e}`;
783					console.error(msg);
784					processingErrors.push(msg);
785				}
786			}
787		}
788	
789		// #{#eaf5a} Fallback: if attachments were prioritized but none produced a receipt,
790		// try body text extraction as a last resort
791		if (!inserted && hasScannable && emailBodyText) {
792			console.log('No receipts from attachments, falling back to email body text');
793			try {
794				const extracted = await processEmailText(emailBodyText);
795	
796				if (extracted) {
797					console.log(
798						'Mistral found receipt data in body text (fallback):',
799						JSON.stringify(extracted, null, 2)
800					);
801	
802					const imageBytes = await textToImage(emailBodyText);
803					const { path } = await uploadToStorage(
804						supabase,
805						userId,
806						imageBytes,
807						'image/svg+xml',
808						'svg'
809					);
810	
811					// #{#rdc4c} #{#rdc5a} Correct the OCR date from the verbatim raw string, then flag.
812					const resolved = resolveOcrReceiptDate(
813						extracted.transaction_date ?? null,
814						extracted.raw_date_text ?? null,
815						new Date()
816					);
817					extracted.transaction_date = resolved.transaction_date;
818					const suspicious = resolved.suspicious_date;
819					if (suspicious) {
820						console.log(
821							`Warning: Suspicious date detected for email receipt (fallback): ${extracted.transaction_date}`
822						);
823	
824						await sendNotificationEmail(
825							resendApiKey,
826							sender,
827							'warning',
828							'Please Check Receipt Date',
829							`The receipt date we found (${extracted.transaction_date}) seems unusual - it's either more than 6 weeks old or in the future. We've saved the receipt, but please verify the date is correct and update it if needed.`,
830							event.data.subject,
831							event.data.email_id
832						);
833					}
834	
835					// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
836					const exchangeRate = await fetchRateForReceipt(
837						extracted.currency,
838						extracted.transaction_date
839					);
840	
841					inserted = await insertReceipt(supabase, {
842						user_id: userId,
843						receipt_image_path: path,
844						merchant_name: extracted.merchant_name,
845						total_amount: extracted.total_amount,
846						tax: extracted.tax,
847						transaction_date: extracted.transaction_date,
848						currency: extracted.currency,
849						exchange_rate_to_cad: exchangeRate,
850						credit_card_name: extracted.credit_card_name,
851						credit_card_last_4: extracted.credit_card_last_4,
852						suspicious_date: suspicious
853					});
854					console.log('Receipt inserted from body text (fallback):', inserted?.id);
855				}
856			} catch (e) {
857				const msg = `Body text fallback error: ${(e as any)?.message || e}`;
858				console.error(msg);
859				processingErrors.push(msg);
860			}
861		}
862	
863		if (!inserted) {
864			// No receipt was found in email body or attachments - notify user
865			await sendNotificationEmail(
866				resendApiKey,
867				sender,
868				'error',
869				'No Receipt Found',
870				`We couldn't find any receipt information in your email or attachments. Please make sure you're forwarding a clear receipt photo or PDF. If you're forwarding text-only emails, they may not contain receipt data we can extract.`,
871				event.data.subject,
872				event.data.email_id
873			);
874	
875			console.error('Processing failed. Errors:', JSON.stringify(processingErrors));
876			return jsonResponse(422, {
877				error: 'No valid receipt found in email body or attachments',
878				details: processingErrors,
879				email_id: event.data.email_id,
880				attachments_count: attachmentMetadata.length,
881				had_body_text: !!emailBodyText,
882				had_scannable_attachments: hasScannable
883			});
884		}
885	
886		// Success! Send confirmation email
887		const merchantInfo = inserted.merchant_name ? ` from ${inserted.merchant_name}` : '';
888		const amountInfo = inserted.total_amount ? ` for $${inserted.total_amount}` : '';
889	
890		await sendNotificationEmail(
891			resendApiKey,
