/**
 * Test Suite for Resend Email Receipt Processing - Date Validation
 *
 * Tests for #{#dtv4a} - Email receipt date validation
 *
 * Authority: developer
 * Priority: High
 *
 * Acceptance Criteria:
 * 1. Resend webhook handler must validate dates after OCR extraction
 * 2. Suspicious dates must set `suspicious_date = true` in inserted receipt
 * 3. Email receipts with suspicious dates must appear in review filter
 * 4. Email processing must not fail due to suspicious dates (warning only)
 * 5. Validation logic must be identical to file upload (#{#dtv1a})
 * 6. Multiple receipts from same email must validate independently
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { isSuspiciousDate } from '../_shared/dateValidation.ts';

// These tests exercise the shared date-validation logic the resend handler
// applies to OCR results before inserting a receipt. They use fake timers so
// the relative-age checks are deterministic.

describe('#{#dtv4a} - Email Receipt Date Validation', () => {
	// Mock date to 2025-12-09
	const TODAY = '2025-12-09T12:00:00Z';

	beforeEach(() => {
		vi.useFakeTimers();
		vi.setSystemTime(new Date(TODAY));
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	describe('Date Validation in Email Processing', () => {
		it('should set suspicious_date = true for old dates from email', async () => {
			const receiptData = {
				user_id: 'test-user',
				receipt_image_path: 'receipts/email-receipt.jpg',
				transaction_date: '2025-07-15', // ~147 days old
				merchant_name: 'Old Email Receipt',
				total_amount: 75.0,
				tax: 7.5,
				suspicious_date: undefined as boolean | undefined // Set by validation below
			};

			// Apply the same validation the resend handler uses before insertReceipt
			receiptData.suspicious_date = isSuspiciousDate(receiptData.transaction_date);

			expect(receiptData.suspicious_date).toBe(true);
		});

		it('should set suspicious_date = false for recent dates from email', async () => {
			const receiptData = {
				user_id: 'test-user',
				receipt_image_path: 'receipts/email-receipt.jpg',
				transaction_date: '2025-12-05', // 4 days old
				merchant_name: 'Recent Email Receipt',
				total_amount: 50.0,
				tax: 5.0,
				suspicious_date: undefined as boolean | undefined // Set by validation below
			};

			receiptData.suspicious_date = isSuspiciousDate(receiptData.transaction_date);

			expect(receiptData.suspicious_date).toBe(false);
		});

		it('should handle null dates from email gracefully', async () => {
			const receiptData = {
				user_id: 'test-user',
				receipt_image_path: 'receipts/email-receipt.jpg',
				transaction_date: null as string | null,
				merchant_name: 'No Date Email Receipt',
				total_amount: 25.0,
				tax: 2.5,
				suspicious_date: undefined as boolean | undefined // Set by validation below
			};

			// Null/missing date is incomplete, not suspicious
			receiptData.suspicious_date = isSuspiciousDate(receiptData.transaction_date);

			expect(receiptData.suspicious_date).toBe(false);
		});
	});

	describe('Multiple Attachments from Same Email', () => {
		it('should validate each attachment independently', async () => {
			const attachments = [
				{ filename: 'receipt1.jpg', transaction_date: '2025-12-05' }, // Recent - not suspicious
				{ filename: 'receipt2.jpg', transaction_date: '2025-07-01' }, // Old - suspicious
				{ filename: 'receipt3.jpg', transaction_date: '2025-12-08' } // Recent - not suspicious
			];

			// Each attachment is validated independently with the shared utility
			const suspiciousFlags = attachments.map((att) => isSuspiciousDate(att.transaction_date));

			expect(suspiciousFlags[0]).toBe(false);
			expect(suspiciousFlags[1]).toBe(true);
			expect(suspiciousFlags[2]).toBe(false);
		});
	});

	describe('Confirmation Workflow Compatibility', () => {
		it('should support "Needs Review" filter for email receipts', async () => {
			// Email receipts with a suspicious date should appear in the review
			// queue alongside file uploads.
			const mixedReceipts = [
				{ id: '1', source: 'file', suspicious_date: true },
				{ id: '2', source: 'email', suspicious_date: true },
				{ id: '3', source: 'file', suspicious_date: false },
				{ id: '4', source: 'email', suspicious_date: false }
			];

			const needsReview = mixedReceipts.filter((r) => r.suspicious_date);

			expect(needsReview.length).toBe(2);
			expect(needsReview.some((r) => r.source === 'email')).toBe(true);
		});
	});
});

