1	// Email notification sender for the Resend webhook handler.
2	//
3	// Extracted from resend/index.ts so it can be unit-tested (index.ts calls
4	// Deno.serve() at import time and cannot load under vitest). The sender now
5	// RETURNS a result instead of swallowing failures — callers must surface a
6	// failed send so notifications don't fail silently.
7	
8	export type NotificationType = 'error' | 'warning' | 'success';
9	
10	export interface SendNotificationResult {
11		ok: boolean;
12		/** HTTP status from Resend, or 0 if the request threw before a response. */
13		status: number;
14		/** Resend email id on success. */
15		id?: string;
16		/** Human-readable failure reason on !ok. */
17		error?: string;
18	}
19	
20	/**
21	 * Resolve the "from" address for notification emails.
22	 *
23	 * MUST be a sender on a domain that is VERIFIED in the Resend account, or every
24	 * send returns 403 "Request is forbidden". Configure via the RESEND_FROM_EMAIL
25	 * secret so the verified address can change without a code deploy. The default
26	 * is intentionally a placeholder — set the env var in Supabase secrets.
27	 */
28	export function resolveFromAddress(): string {
29		const denoEnv = (globalThis as { Deno?: { env?: { get?(key: string): string | undefined } } })
30			.Deno?.env;
31		const configured = denoEnv?.get?.('RESEND_FROM_EMAIL');
32		return configured && configured.trim().length > 0
33			? configured
34			: 'Expense Tracker <receipts@yourfinanciallaunchpad.com>';
35	}
36	
37	function buildHtml(
38		notificationType: NotificationType,
39		title: string,
40		message: string,
41		originalSubject: string,
42		sentAt: string,
43		emailId?: string
44	): string {
45		const iconMap = { error: '❌', warning: '⚠️', success: '✅' };
46		const colorMap = { error: '#dc2626', warning: '#f59e0b', success: '#16a34a' };
47		const icon = iconMap[notificationType];
48		const color = colorMap[notificationType];
49	
50		return `
51	<!DOCTYPE html>
52	<html>
53	<head>
54		<style>
55			body {
56				font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
57				line-height: 1.6;
58				color: #333;
59			}
60			.container {
61				max-width: 600px;
62				margin: 0 auto;
63				padding: 20px;
64			}
65			.header {
66				text-align: center;
67				padding: 20px 0;
68			}
69			.icon {
70				font-size: 48px;
71				margin-bottom: 10px;
72			}
73			.notification-box {
74				background: #f9fafb;
75				border-left: 4px solid ${color};
76				padding: 20px;
77				margin: 20px 0;
78				border-radius: 4px;
79			}
80			.notification-box h2 {
81				margin-top: 0;
82				color: ${color};
83			}
84			.actions {
85				background: #ffffff;
86				border: 1px solid #e5e7eb;
87				border-radius: 8px;
88				padding: 20px;
89				margin: 20px 0;
90			}
91			.actions h3 {
92				margin-top: 0;
93				font-size: 16px;
94			}
95			.actions ul {
96				margin: 10px 0;
97				padding-left: 20px;
98			}
99			.actions li {
100				margin: 8px 0;
101			}
102			.cta-button {
103				display: inline-block;
104				background: #2563eb;
105				color: white !important;
106				padding: 12px 24px;
107				text-decoration: none;
108				border-radius: 6px;
109				margin: 15px 0 5px 0;
110				font-weight: 500;
111			}
112			.footer {
113				margin-top: 30px;
114				padding-top: 20px;
115				border-top: 1px solid #e5e7eb;
116				color: #6b7280;
117				font-size: 13px;
118			}
119			.footer-info {
120				margin: 5px 0;
121			}
122		</style>
123	</head>
124	<body>
125		<div class="container">
126			<div class="header">
127				<div class="icon">${icon}</div>
128			</div>
129	
130			<div class="notification-box">
131				<h2>${title}</h2>
132				<p>${message}</p>
133			</div>
134	
135			${
136				notificationType === 'error' || notificationType === 'warning'
137					? `
138			<div class="actions">
139				<h3>What you can do:</h3>
140				<ul>
141					<li>📸 Forward the email again with a clearer, well-lit photo</li>
142					<li>📄 Send the receipt as a PDF attachment instead of an image</li>
143					<li>🖼️ Make sure the entire receipt is visible and in focus</li>
144					<li>💻 Upload directly through the web app (see button below)</li>
145				</ul>
146				<a href="https://app.yourfinanciallaunchpad.com/receipts" class="cta-button">
147					Upload Receipt Directly
148				</a>
149			</div>
150			`
151					: ''
152			}
153	
154			<div class="footer">
155				<div class="footer-info"><strong>Original email:</strong> "${originalSubject}"</div>
156				<div class="footer-info"><strong>Sent at:</strong> ${sentAt}</div>
157				${emailId ? `<div class="footer-info"><strong>Email ID:</strong> ${emailId}</div>` : ''}
158				<div class="footer-info" style="margin-top: 15px;">
159					<em>This is an automated notification from your expense tracker.</em>
160				</div>
161			</div>
162		</div>
163	</body>
164	</html>
165		`;
166	}
167	
168	/**
169	 * Send an email notification to the user about receipt processing status.
170	 *
171	 * Returns a {@link SendNotificationResult}. Unlike the previous implementation,
172	 * it does NOT swallow failures: a non-2xx response or a thrown request produces
173	 * `{ ok: false, ... }` so the caller can record the failure durably (in-app
174	 * notice + admin alert). It still never throws — the webhook must keep
175	 * processing even when notifications can't be delivered.
176	 */
177	export async function sendNotificationEmail(
178		apiKey: string,
179		toEmail: string,
180		notificationType: NotificationType,
181		title: string,
182		message: string,
183		originalSubject: string,
184		emailId?: string
185	): Promise<SendNotificationResult> {
186		const subjectPrefix = { error: 'Failed', warning: 'Warning', success: 'Success' };
187		const subject = `Receipt ${subjectPrefix[notificationType]}: "${originalSubject}"`;
188		const from = resolveFromAddress();
189		const html = buildHtml(
190			notificationType,
191			title,
192			message,
193			originalSubject,
194			new Date().toLocaleString(),
195			emailId
196		);
197	
198		try {
199			const response = await fetch('https://api.resend.com/emails', {
200				method: 'POST',
201				headers: {
202					Authorization: `Bearer ${apiKey}`,
203					'Content-Type': 'application/json'
204				},
205				body: JSON.stringify({ from, to: [toEmail], subject, html })
206			});
207	
208			if (!response.ok) {
209				const errorText = await response.text();
210				console.error('Failed to send notification email:', response.status, errorText);
211				return {
212					ok: false,
213					status: response.status,
214					error: `Resend responded ${response.status}: ${errorText}`
215				};
216			}
217	
218			const result = (await response.json().catch(() => ({}))) as { id?: string };
219			console.log(`Notification email sent to ${toEmail}:`, result);
220			return { ok: true, status: response.status, id: result?.id };
221		} catch (err) {
222			console.error('Error sending notification email:', err);
223			return { ok: false, status: 0, error: err instanceof Error ? err.message : String(err) };
224		}
225	}

